def main():
    assert len(PREDS) == 20, f"本批应20例，实际{len(PREDS)}"
    ids = [p["case_id"] for p in PREDS]
    assert len(set(ids)) == 20
    for p in PREDS:
        path = os.path.join(BASE, p["case_id"] + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(p, f, ensure_ascii=False, indent=1)
    # 自验：回读解析、字段齐备、case_id与文件名对位
    n = 0
    for p in PREDS:
        path = os.path.join(BASE, p["case_id"] + ".json")
        d = json.load(open(path, encoding="utf-8"))
        assert d["case_id"] == p["case_id"] == os.path.basename(path)[:-5]
        for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
            assert k in d, (p["case_id"], k)
        t = d["trigger"]
        for k in ("changed_main", "reserve_used", "disputed", "reason"):
            assert k in t
        assert isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1
        n += 1
    print(f"WROTE_AND_VERIFIED={n}")

if __name__ == "__main__":
    main()
